import os
import torch
import numpy as np
import random


class Config:
    """
    Configuration class for the Cervical Spine Fracture Detection task.
    Stores hyperparameters, constants, and file paths.
    """

    # --- Reproducibility ---
    SEED = 42

    # --- File Paths ---
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"

    # Image Directories
    TRAIN_IMAGES_DIR = os.path.join(INPUT_DIR, "train_images")
    TEST_IMAGES_DIR = os.path.join(INPUT_DIR, "test_images")

    # Metadata Files (Generated by the provided metadata script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Paths
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_1")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --- Data Preprocessing Hyperparameters ---
    # Image dimensions for the 2D CNN backbone
    IMG_SIZE = 256

    # Number of slices to uniformly subsample from the 3D volume
    # This creates the "bag" of instances for MIL
    NUM_SLICES = 64

    # Input channels (1 for grayscale)
    IN_CHANNELS = 1

    # DICOM Windowing for Bone (Hounsfield Units)
    BONE_WINDOW_CENTER = 500
    BONE_WINDOW_WIDTH = 2000

    # --- Model & Training Hyperparameters ---
    # Classes: C1-C7 (7) + patient_overall (1) = 8 targets
    N_CLASSES = 8

    # Top K slices to average for MIL aggregation
    TOP_K = 10

    # Training settings
    BATCH_SIZE = 4  # Batch size of studies (bags)
    EPOCHS = 10
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2
    DROPOUT = 0.5
    NUM_WORKERS = 4  # For DataLoader

    # Compute
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @staticmethod
    def setup_directories():
        """Creates necessary directories for caching and submission."""
        os.makedirs(Config.CACHE_DIR, exist_ok=True)
        os.makedirs(Config.SUBMISSION_DIR, exist_ok=True)

    @staticmethod
    def seed_everything(seed=42):
        """Sets the random seed for python, numpy, and torch to ensure reproducibility."""
        random.seed(seed)
        os.environ["PYTHONHASHSEED"] = str(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed(seed)
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False


# Automatically setup environment when config is imported
Config.setup_directories()
Config.seed_everything(Config.SEED)
